script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var deviceSelect = document.getElementById('deviceSelect');
  var micSelect = document.getElementById('micSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnRecord = document.getElementById('btnRecord');
  var selectDurationCap = document.getElementById('selectDurationCap');
  var recordTimer = document.getElementById('recordTimer');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var recordingEmpty = document.getElementById('recordingEmpty');
  var recordingPlayback = document.getElementById('recordingPlayback');
  var recordingStats = document.getElementById('recordingStats');
  var statDuration = document.getElementById('statDuration');
  var statFileSize = document.getElementById('statFileSize');
  var statFormat = document.getElementById('statFormat');
  var btnDownloadRecording = document.getElementById('btnDownloadRecording');
  var btnMirror = document.getElementById('btnMirrorToggle');
  var checkAudio = document.getElementById('checkAudio');
  var selectQuality = document.getElementById('selectQuality');
  var selectFormat = document.getElementById('selectFormat');
  var inputVideoBitrate = document.getElementById('inputVideoBitrate');
  var inputAudioBitrate = document.getElementById('inputAudioBitrate');
  var checkVideoBitrate = document.getElementById('checkVideoBitrate');
  var checkAudioBitrate = document.getElementById('checkAudioBitrate');
  var inputPlanMinutes = document.getElementById('inputPlanMinutes');
  var inputPlanSeconds = document.getElementById('inputPlanSeconds');
  var estSize = document.getElementById('estSize');
  var estCombined = document.getElementById('estCombined');
  var estPerMinute = document.getElementById('estPerMinute');
  var estVideo = document.getElementById('estVideo');
  var estAudio = document.getElementById('estAudio');
  var estResolution = document.getElementById('estResolution');
  var statResolution = document.getElementById('statResolution');
  var statSavedFile = document.getElementById('statSavedFile');

  var currentStream = null;
  var currentDeviceId = '';
  var currentMicId = '';
  var starting = false;
  var mediaRecorder = null;
  var recordedChunks = [];
  var recordingUrl = null;
  var recordStartTime = 0;
  var recordTickInterval = null;
  var recordCapTimeout = null;

  // Preference order: VP9 compresses best, VP8 is the broadest fallback,
  // plain webm/mp4 last. Feature-detected with isTypeSupported rather than
  // assumed -- codec support diverges sharply between Chrome/Edge/Firefox
  // and Safari, per this tool's own spec.
  var MIME_CANDIDATES = [
    'video/webm;codecs=vp9,opus',
    'video/webm;codecs=vp8,opus',
    'video/webm',
    'video/mp4;codecs=avc1.42E01E,mp4a.40.2',
    'video/mp4',
  ];
  var MIME_LABELS = {
    'video/webm;codecs=vp9,opus': 'WebM (VP9)',
    'video/webm;codecs=vp8,opus': 'WebM (VP8)',
    'video/webm': 'WebM (browser default codec)',
    'video/mp4;codecs=avc1.42E01E,mp4a.40.2': 'MP4 (H.264 + AAC)',
    'video/mp4': 'MP4 (browser default codec)',
  };
  var QUALITY = { '1080': [1920, 1080], '720': [1280, 720], '480': [640, 480] };
  // Typical rates the size estimate assumes when bitrate is left on auto.
  var TYPICAL_VIDEO_KBPS = [[2160, 12000], [1440, 6000], [1080, 3600], [720, 2000], [0, 1000]];
  var TYPICAL_AUDIO_KBPS = 160;

  function pickMimeType() {
    if (typeof MediaRecorder === 'undefined' || !MediaRecorder.isTypeSupported) return '';
    if (selectFormat.value && MediaRecorder.isTypeSupported(selectFormat.value)) return selectFormat.value;
    for (var i = 0; i < MIME_CANDIDATES.length; i++) {
      if (MediaRecorder.isTypeSupported(MIME_CANDIDATES[i])) return MIME_CANDIDATES[i];
    }
    return '';
  }

  // Known immediately on load, independent of camera/mic permission --
  // renders the exact preference list pickMimeType() walks, so the "why
  // did I get .webm" answer is visible before the visitor ever records.
  function renderCodecSupportTable() {
    var table = document.getElementById('codecSupportTable');
    var supported = typeof MediaRecorder !== 'undefined' && !!MediaRecorder.isTypeSupported;
    table.innerHTML = MIME_CANDIDATES.map(function (mime) {
      var ok = supported && MediaRecorder.isTypeSupported(mime);
      return '<div class="info-row"><span class="info-label">' + escapeHtml(mime) + '</span>' +
        '<span class="info-value' + (ok ? '' : ' unsupported') + '">' + (ok ? 'Supported' : 'Not supported') + '</span></div>';
    }).join('');
    // The file-format picker offers only what this browser can record.
    MIME_CANDIDATES.forEach(function (mime) {
      if (!supported || !MediaRecorder.isTypeSupported(mime)) return;
      var opt = document.createElement('option');
      opt.value = mime;
      opt.textContent = MIME_LABELS[mime] || mime;
      selectFormat.appendChild(opt);
    });
  }

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function formatBytes(n) {
    if (n < 1024) return n + ' B';
    if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB';
    return (n / (1024 * 1024)).toFixed(2) + ' MB';
  }

  function formatSeconds(s) {
    var m = Math.floor(s / 60), rem = Math.floor(s % 60);
    return m + ':' + (rem < 10 ? '0' : '') + rem;
  }

  function fileName(mimeType) {
    return 'webcam-recording.' + (mimeType && mimeType.indexOf('mp4') !== -1 ? 'mp4' : 'webm');
  }

  function typicalVideoKbps(height) {
    for (var i = 0; i < TYPICAL_VIDEO_KBPS.length; i++) if (height >= TYPICAL_VIDEO_KBPS[i][0]) return TYPICAL_VIDEO_KBPS[i][1];
    return 1000;
  }

  // File size = (video + audio kbit/s) x seconds / 8,000.
  function updateEstimate() {
    var q = selectQuality.value;
    var liveW = currentStream ? video.videoWidth : 0, liveH = currentStream ? video.videoHeight : 0;
    var h, label;
    if (liveH) { h = liveH; label = liveW + '\u00d7' + liveH; }
    else if (QUALITY[q]) { h = QUALITY[q][1]; label = QUALITY[q][0] + '\u00d7' + QUALITY[q][1] + ' (requested)'; }
    else { h = 1080; label = q === 'max' ? 'Detected on start' : 'Camera default'; }
    var v = checkVideoBitrate.checked ? Math.max(0, parseFloat(inputVideoBitrate.value) || 0) : typicalVideoKbps(h);
    var a = checkAudio.checked ? (checkAudioBitrate.checked ? Math.max(0, parseFloat(inputAudioBitrate.value) || 0) : TYPICAL_AUDIO_KBPS) : 0;
    var secs = Math.max(0, (parseFloat(inputPlanMinutes.value) || 0) * 60 + (parseFloat(inputPlanSeconds.value) || 0));
    var mb = function (kbps, s) { return kbps * s / 8000; };
    estSize.textContent = mb(v + a, secs).toFixed(2) + ' MB';
    estCombined.textContent = Math.round(v + a).toLocaleString() + ' kbit/s';
    estPerMinute.textContent = mb(v + a, 60).toFixed(1) + ' MB';
    estVideo.textContent = mb(v, secs).toFixed(2) + ' MB';
    estAudio.textContent = a ? mb(a, secs).toFixed(2) + ' MB' : 'None (muted)';
    estResolution.textContent = label;
  }

  function clearRecordTimers() {
    if (recordTickInterval) { clearInterval(recordTickInterval); recordTickInterval = null; }
    if (recordCapTimeout) { clearTimeout(recordCapTimeout); recordCapTimeout = null; }
    recordTimer.textContent = '';
  }

  // Stops the in-progress MediaRecorder (if any) WITHOUT touching
  // currentStream -- called both from the normal stop-recording path and
  // from stopStream()'s teardown, so a recorder is never left running
  // against tracks that are about to be (or already were) stopped.
  function stopRecordingIfActive() {
    clearRecordTimers();
    if (mediaRecorder && mediaRecorder.state !== 'inactive') {
      mediaRecorder.stop();
    }
  }

  // Every camera page on this site copies this stopStream()/enumerate/error
  // pattern from webcam-test-online.json (see this project's own CLAUDE.md).
  // This tool additionally stops any in-progress recording first, so the
  // recorder never fires a dataavailable/stop event against tracks that
  // have already been released.
  function stopStream() {
    stopRecordingIfActive();
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnRecord.disabled = true;
    btnMirror.disabled = true;
    selectDurationCap.disabled = true;
    btnRecord.textContent = 'Start Recording';
    btnRecord.classList.remove('active');
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera or microphone access was blocked.</strong> Click the camera icon in your address bar (or your browser\u2019s site settings) and allow both, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera or microphone was detected.</strong> Make sure both are connected, then reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera or microphone is already in use.</strong> Another app or browser tab is probably holding it \u2014 close video-calling apps or other camera tabs and try again.' };
      case 'OverconstrainedError':
      case 'ConstraintNotSatisfiedError':
        return { sev: 'error', html: '<strong>This device doesn\u2019t support the requested settings.</strong> Try a different camera or microphone from the lists above.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera and microphone access require a secure connection.</strong> Make sure this page is loaded over HTTPS.' };
      case 'AbortError':
        return { sev: 'warn', html: 'The request was interrupted. Click <strong>Start Camera</strong> to try again.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera or microphone.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateSelect(select, devices, kind, currentId, emptyLabel, labelPrefix) {
    var list = devices.filter(function (d) { return d.kind === kind; });
    select.innerHTML = '';
    if (!list.length) {
      var opt = document.createElement('option');
      opt.value = '';
      opt.textContent = emptyLabel;
      select.appendChild(opt);
      select.disabled = true;
      return;
    }
    list.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || (labelPrefix + ' ' + (i + 1));
      if (d.deviceId === currentId) opt.selected = true;
      select.appendChild(opt);
    });
    select.disabled = false;
  }

  function refreshDeviceLists() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return Promise.resolve();
    return navigator.mediaDevices.enumerateDevices().then(function (devices) {
      populateSelect(deviceSelect, devices, 'videoinput', currentDeviceId, 'No cameras found', 'Camera');
      populateSelect(micSelect, devices, 'audioinput', currentMicId, 'No microphones found', 'Microphone');
    }).catch(function () {});
  }

  function startStream(deviceId, micId) {
    if (starting) return;
    starting = true;
    stopStream();
    var withAudio = checkAudio.checked;
    setDiagnostic([{ sev: '', html: withAudio ? 'Requesting camera and microphone access\u2026' : 'Requesting camera access\u2026' }]);
    btnStart.disabled = true;

    var videoConstraint = {};
    var q = selectQuality.value;
    if (q === 'max') { videoConstraint.width = { ideal: 4096 }; videoConstraint.height = { ideal: 2160 }; }
    else if (QUALITY[q]) { videoConstraint.width = { ideal: QUALITY[q][0] }; videoConstraint.height = { ideal: QUALITY[q][1] }; }
    if (deviceId) videoConstraint.deviceId = { exact: deviceId };
    if (!Object.keys(videoConstraint).length) videoConstraint = true;
    var audioConstraint = withAudio ? (micId ? { deviceId: { exact: micId } } : true) : false;
    navigator.mediaDevices.getUserMedia({ video: videoConstraint, audio: audioConstraint })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var vTrack = stream.getVideoTracks()[0];
        var aTrack = stream.getAudioTracks()[0];
        var vSettings = vTrack && vTrack.getSettings ? vTrack.getSettings() : {};
        currentDeviceId = vSettings.deviceId || deviceId || '';
        var aSettings = aTrack && aTrack.getSettings ? aTrack.getSettings() : {};
        currentMicId = aSettings.deviceId || micId || '';
        btnStop.disabled = false;
        btnMirror.disabled = false;
        btnRecord.disabled = !pickMimeType();
        selectDurationCap.disabled = false;
        updateEstimate();
        if (!pickMimeType()) {
          setDiagnostic([{ sev: 'warn', html: '<strong>Camera and microphone are live,</strong> but this browser doesn\u2019t support video recording (MediaRecorder). You can still use this as a live preview.' }]);
        } else {
          setDiagnostic([{ sev: 'ok', html: '<strong>Camera and microphone are live.</strong> Click <strong>Start Recording</strong> to record a clip.' }]);
        }
        return refreshDeviceLists().then(function () {
          if (!checkAudio.checked) micSelect.disabled = true;
        });
      })
      .catch(function (err) {
        setDiagnostic([describeError(err)]);
      })
      .finally(function () {
        starting = false;
        btnStart.disabled = false;
      });
  }

  function setRecordedResult(blob, mimeType, durationS, size) {
    if (recordingUrl) URL.revokeObjectURL(recordingUrl);
    recordingUrl = URL.createObjectURL(blob);
    recordingPlayback.src = recordingUrl;
    recordingPlayback.classList.remove('u-hidden');
    recordingPlayback.style.display = 'block';
    recordingEmpty.style.display = 'none';
    // The stats grid starts hidden via the u-hidden class, so it has to be
    // removed (clearing an inline style alone never revealed it).
    recordingStats.classList.remove('u-hidden');
    recordingStats.style.display = '';
    statDuration.textContent = formatSeconds(durationS);
    statFileSize.textContent = formatBytes(blob.size);
    statFormat.textContent = mimeType || 'Unknown';
    statResolution.textContent = size && size.w ? size.w + '\u00d7' + size.h : '\u2014';
    statSavedFile.textContent = fileName(mimeType);
    btnDownloadRecording.href = recordingUrl;
    btnDownloadRecording.setAttribute('download', fileName(mimeType));
  }

  function startRecording() {
    if (!currentStream) return;
    var mimeType = pickMimeType();
    if (!mimeType) return;
    recordedChunks = [];
    var opts = { mimeType: mimeType };
    if (checkVideoBitrate.checked) opts.videoBitsPerSecond = Math.max(100, parseFloat(inputVideoBitrate.value) || 2500) * 1000;
    if (checkAudioBitrate.checked && currentStream.getAudioTracks().length) opts.audioBitsPerSecond = Math.max(16, parseFloat(inputAudioBitrate.value) || 160) * 1000;
    var vs = currentStream.getVideoTracks()[0].getSettings ? currentStream.getVideoTracks()[0].getSettings() : {};
    var recSize = { w: video.videoWidth || vs.width, h: video.videoHeight || vs.height };
    try {
      mediaRecorder = new MediaRecorder(currentStream, opts);
    } catch (e) {
      setDiagnostic([{ sev: 'error', html: '<strong>Could not start recording.</strong> Your browser reported: ' + escapeHtml(e.message || 'unknown error') + '.' }]);
      return;
    }
    var capSeconds = parseInt(selectDurationCap.value, 10) || 20;
    recordStartTime = Date.now();

    mediaRecorder.addEventListener('dataavailable', function (e) {
      if (e.data && e.data.size > 0) recordedChunks.push(e.data);
    });
    mediaRecorder.addEventListener('stop', function () {
      clearRecordTimers();
      btnRecord.textContent = 'Start Recording';
      btnRecord.classList.remove('active');
      var elapsedS = (Date.now() - recordStartTime) / 1000;
      if (recordedChunks.length) {
        var blob = new Blob(recordedChunks, { type: mimeType });
        setRecordedResult(blob, mimeType, elapsedS, recSize);
        setDiagnostic([{ sev: 'ok', html: '<strong>Recording saved.</strong> Review it on the right, or download it.' }]);
      }
      recordedChunks = [];
    });

    // A 1-second timeslice keeps memory in small chunks on the longer caps.
    mediaRecorder.start(1000);
    btnRecord.textContent = 'Stop Recording';
    btnRecord.classList.add('active');
    setDiagnostic([{ sev: '', html: '<span class="recording-dot"></span> Recording\u2026' }]);

    recordTickInterval = setInterval(function () {
      var elapsed = (Date.now() - recordStartTime) / 1000;
      recordTimer.textContent = formatSeconds(elapsed) + ' / ' + formatSeconds(capSeconds);
    }, 250);
    // Duration cap: MediaRecorder has no built-in max-length option, so a
    // plain timeout stops it once the cap elapses -- also the main defence
    // against unbounded memory growth on a long recording, per this tool's
    // own spec.
    recordCapTimeout = setTimeout(function () {
      if (mediaRecorder && mediaRecorder.state === 'recording') mediaRecorder.stop();
    }, capSeconds * 1000);
  }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value, micSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped. Click <strong>Start Camera</strong> to test again.' }]);
  });
  btnRecord.addEventListener('click', function () {
    if (mediaRecorder && mediaRecorder.state === 'recording') {
      mediaRecorder.stop();
    } else {
      startRecording();
    }
  });
  deviceSelect.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value, micSelect.value);
  });
  micSelect.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value, micSelect.value);
  });

  function isRecording() { return !!(mediaRecorder && mediaRecorder.state !== 'inactive'); }

  btnMirror.addEventListener('click', function () {
    // Preview only: the saved file keeps the natural (unmirrored) view.
    var mirrored = previewWrap.classList.toggle('is-mirrored');
    btnMirror.setAttribute('aria-pressed', mirrored ? 'true' : 'false');
    btnMirror.classList.toggle('active', mirrored);
  });
  selectQuality.addEventListener('change', function () {
    updateEstimate();
    if (currentStream && !isRecording()) startStream(deviceSelect.value, micSelect.value);
  });
  checkAudio.addEventListener('change', function () {
    updateEstimate();
    if (currentStream && !isRecording()) startStream(deviceSelect.value, micSelect.value);
    else if (!checkAudio.checked) micSelect.disabled = true;
  });
  checkVideoBitrate.addEventListener('change', function () { inputVideoBitrate.disabled = !checkVideoBitrate.checked; updateEstimate(); });
  checkAudioBitrate.addEventListener('change', function () { inputAudioBitrate.disabled = !checkAudioBitrate.checked; updateEstimate(); });
  [inputVideoBitrate, inputAudioBitrate, inputPlanMinutes, inputPlanSeconds].forEach(function (el) {
    el.addEventListener('input', updateEstimate);
  });
  video.addEventListener('loadedmetadata', updateEstimate);

  // Guaranteed teardown: stop any in-progress recording and release the
  // camera/microphone the moment the visitor leaves this page, and revoke
  // the recorded blob's object URL so it isn't held in memory forever.
  window.addEventListener('pagehide', function () {
    stopStream();
    if (recordingUrl) { URL.revokeObjectURL(recordingUrl); recordingUrl = null; }
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  renderCodecSupportTable();
  updateEstimate();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn\u2019t support camera access.</strong> Try the latest version of Chrome, Firefox, Edge, or Safari.' }]);
    btnStart.disabled = true;
  } else if (typeof MediaRecorder === 'undefined') {
    setDiagnostic([{ sev: 'warn', html: 'Your browser supports camera access but not video recording (MediaRecorder). You can still preview your camera, but recording won\u2019t be available.' }]);
  }
})();
